import{_ as a,o,c as t,ag as i}from"./chunks/framework.wGDfT7ie.js";const f=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),r={name:"faq.md"};function s(n,e,d,h,l,c){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="who-is-zkde-fi-for" tabindex="-1">Who is zkde.fi for? <a class="header-anchor" href="#who-is-zkde-fi-for" aria-label="Permalink to &quot;Who is zkde.fi for?&quot;">​</a></h2><p>Users who want DeFi allocation (e.g. across pools or protocols) with <strong>privacy</strong> and <strong>verifiability</strong>: intent-hiding, confidential balances, and the ability to prove compliance or eligibility without revealing their full history. Suited for DAOs, funds, and individuals who care about MEV protection and selective disclosure.</p><h2 id="is-my-data-private" tabindex="-1">Is my data private? <a class="header-anchor" href="#is-my-data-private" aria-label="Permalink to &quot;Is my data private?&quot;">​</a></h2><ul><li><strong>Proof-gated execution</strong>: Your intent (e.g. “deposit 100 into pool A”) is not broadcast until the proof is ready and you sign. The chain sees the verified action, not your raw strategy.</li><li><strong>Confidential transfers</strong>: Amounts and balances are hidden behind commitments. Only you (and anyone you share the opening with) can see the real amounts.</li><li><strong>Selective disclosure</strong>: You choose what to prove (e.g. “yield above X”). The rest of your history is not revealed.</li></ul><h2 id="what-is-a-proof-gated-deposit" tabindex="-1">What is a “proof-gated” deposit? <a class="header-anchor" href="#what-is-a-proof-gated-deposit" aria-label="Permalink to &quot;What is a “proof-gated” deposit?&quot;">​</a></h2><p>A deposit that the smart contract only executes if you provide a <strong>valid proof</strong> that the action satisfies your constraints (e.g. max position, allowed protocols). The proof is verified on-chain via Integrity. So the chain never executes an out-of-policy action.</p><h2 id="what-chain-is-zkde-fi-on" tabindex="-1">What chain is zkde.fi on? <a class="header-anchor" href="#what-chain-is-zkde-fi-on" aria-label="Permalink to &quot;What chain is zkde.fi on?&quot;">​</a></h2><p><strong>Starknet</strong> (Sepolia for the demo; mainnet when we ship). You need a Starknet wallet (e.g. ArgentX, Braavos) and Sepolia ETH for gas.</p><h2 id="is-it-open-source" tabindex="-1">Is it open source? <a class="header-anchor" href="#is-it-open-source" aria-label="Permalink to &quot;Is it open source?&quot;">​</a></h2><p>Yes. The app and contracts are open source. See the <a href="https://github.com/obsqra-labs/zkdefi" target="_blank" rel="noreferrer">GitHub repo</a> and <a href="/docs/developers.html">For developers</a> for more.</p><p>Next: <a href="/docs/developers.html">For developers</a></p>',12)])])}const u=a(r,[["render",s]]);export{f as __pageData,u as default};
